<template>
    <div class="browse-teams-view">
        <div class="browse-teams-header">
            <h2>{{ t('teamhub', 'Browse teams') }}</h2>
            <p class="browse-teams-subtitle">
                {{ t('teamhub', 'Discover and join teams in the organization') }}
            </p>
        </div>

        <!-- Search and view controls -->
        <div class="browse-teams-controls">
            <!-- NcTextField default slot in @nextcloud/vue 8.x renders a
                 trailing icon button that overlays the input and intercepts
                 clicks — the input never receives focus, so no cursor and
                 no typing. The proven maintenance-tab pattern omits the
                 slot; we match it here. -->
            <NcTextField
                v-model="searchQuery"
                :label="t('teamhub', 'Search teams')"
                :placeholder="t('teamhub', 'Search by name or description...')"
                class="browse-teams-search" />

            <div class="browse-teams-view-toggle">
                <NcButton
                    :variant="viewMode === 'grid' ? 'primary' : 'tertiary'"
                    :aria-label="t('teamhub', 'Grid view')"
                    @click="viewMode = 'grid'">
                    <template #icon><ViewGrid :size="ICON_BODY" /></template>
                </NcButton>
                <NcButton
                    :variant="viewMode === 'list' ? 'primary' : 'tertiary'"
                    :aria-label="t('teamhub', 'List view')"
                    @click="viewMode = 'list'">
                    <template #icon><ViewList :size="ICON_BODY" /></template>
                </NcButton>
            </div>
        </div>

        <div v-if="loading" class="browse-teams-loading">
            <NcLoadingIcon :size="ICON_HERO" />
            <p>{{ t('teamhub', 'Loading teams...') }}</p>
        </div>

        <div v-else-if="filteredTeams.length === 0" class="browse-teams-empty">
            <AccountGroup :size="ICON_HERO" />
            <h3>{{ t('teamhub', searchQuery ? 'No teams match your search' : 'No teams found') }}</h3>
            <p>{{ searchQuery ? t('teamhub', 'Try a different search term') : t('teamhub', 'There are no teams available to join') }}</p>
        </div>

        <div v-else :class="['browse-teams-list', `browse-teams-list--${viewMode}`]">
            <div v-for="team in filteredTeams" :key="team.id" class="team-card">
                <!-- Header: icon + info side by side -->
                <div class="team-card__header">
                    <!-- Fixed-size icon container keeps card heights consistent -->
                    <div class="team-card__icon-wrap">
                        <img
                            v-if="team.image_url"
                            :src="team.image_url"
                            :alt="team.name"
                            class="team-card__icon team-card__icon--image" />
                        <AccountGroup v-else :size="ICON_XL" class="team-card__icon" />
                    </div>
                    <div class="team-card__info">
                        <div class="team-card__name-row">
                            <h3 class="team-card__name">{{ team.name }}</h3>
                            <!-- v4.0.2 — template badge fed by teamhub_team_type.
                                 Legacy teams (team.template=null) render nothing. -->
                            <span
                                v-if="templateLabel(team)"
                                class="team-card__type-badge"
                                :title="templateTooltip(team)">
                                {{ templateLabel(team) }}
                            </span>
                        </div>
                        <!-- v4.8.0 — Nextcloud tags. Members only: the
                             backend sends an empty list for a team the
                             viewer is not in, the same boundary image_url
                             draws. Text, never colour alone (WCAG 1.4.1);
                             the tag colour is a dot beside the name. -->
                        <ul v-if="team.tags && team.tags.length" class="team-card__tags">
                            <li v-for="tag in team.tags" :key="tag.id" class="team-card__tag">
                                <span
                                    v-if="tag.color"
                                    class="team-card__tag-dot"
                                    :style="{ backgroundColor: '#' + tag.color }"
                                    aria-hidden="true" />
                                {{ tag.name }}
                            </li>
                        </ul>
                        <p v-if="team.description" class="team-card__description">
                            {{ team.description }}
                        </p>
                        <p v-else class="team-card__description team-card__description--empty">
                            {{ t('teamhub', 'No description') }}
                        </p>
                    </div>
                </div>

                <!-- Actions always pinned to card bottom -->
                <div class="team-card__actions">
                    <!-- Direct member: Open + Leave -->
                    <template v-if="team.isMember && team.isDirectMember">
                        <NcButton
                            variant="secondary"
                            :disabled="actionInProgress[team.id]"
                            @click="openTeam(team)">
                            <template #icon>
                                <OpenInApp :size="ICON_BODY" />
                            </template>
                            {{
                                // TRANSLATORS: button label to open this team and view its content
                                t('teamhub', 'Open')
                            }}
                        </NcButton>
                        <NcButton
                            variant="error"
                            :disabled="actionInProgress[team.id]"
                            @click="leaveTeam(team)">
                            <template #icon>
                                <NcLoadingIcon v-if="actionInProgress[team.id]" :size="ICON_BODY" />
                                <ExitToApp v-else :size="ICON_BODY" />
                            </template>
                            {{
                                // TRANSLATORS: button label to leave (depart from) a team the user is currently a member of
                                t('teamhub', 'Leave')
                            }}
                        </NcButton>
                    </template>

                    <!-- Indirect member (via group/team): Open + disabled Leave with tooltip -->
                    <template v-else-if="team.isMember && !team.isDirectMember">
                        <NcButton
                            variant="secondary"
                            :disabled="actionInProgress[team.id]"
                            @click="openTeam(team)">
                            <template #icon>
                                <OpenInApp :size="ICON_BODY" />
                            </template>
                            {{ t('teamhub', 'Open') }}
                        </NcButton>
                        <span
                            class="team-card__indirect-label"
                            :title="t('teamhub', 'You were added to this team through a group or another team. Ask your administrator to remove you.')">
                            <NcButton variant="tertiary" :disabled="true">
                                <template #icon><ExitToApp :size="ICON_BODY" /></template>
                                {{
                                    // TRANSLATORS: disabled button label; user cannot leave because they were added via a group
                                    t('teamhub', 'Leave')
                                }}
                            </NcButton>
                            <span class="team-card__via-badge">{{ t('teamhub', 'via group') }}</span>
                        </span>
                    </template>

                    <!-- Non-member, team is open: join and land in it -->
                    <NcButton
                        v-else-if="team.joinPolicy === 'open'"
                        variant="primary"
                        :disabled="actionInProgress[team.id]"
                        @click="joinTeam(team)">
                        <template #icon>
                            <NcLoadingIcon v-if="actionInProgress[team.id]" :size="ICON_BODY" />
                            <Plus v-else :size="ICON_BODY" />
                        </template>
                        {{
                            // TRANSLATORS: button label to join (become a member of) a team
                            t('teamhub', 'Join')
                        }}
                    </NcButton>

                    <!-- Non-member, team is open but a moderator approves -->
                    <NcButton
                        v-else-if="team.joinPolicy === 'request'"
                        variant="secondary"
                        :disabled="actionInProgress[team.id]"
                        @click="requestAccess(team)">
                        <template #icon>
                            <NcLoadingIcon v-if="actionInProgress[team.id]" :size="ICON_BODY" />
                            <AccountQuestion v-else :size="ICON_BODY" />
                        </template>
                        {{ t('teamhub', 'Request access') }}
                    </NcButton>

                    <!-- v4.6.17 — invite-only team, visible but not joinable.
                         Before this version it offered Request Access, which
                         Circles refuses; a label states the fact instead. Per
                         SKILLS.md § Permissions an action a role cannot take is
                         hidden, not shown disabled — so there is no button here
                         at all, only the reason there isn't one. -->
                    <span v-else class="team-card__invite-only">
                        {{
                            // TRANSLATORS: status label; this team admits new members by invitation only, so there is nothing to click
                            t('teamhub', 'Invite only')
                        }}
                    </span>
                </div>
            </div>
        </div>
    </div>
</template>

<script>
import { translate as t } from '@nextcloud/l10n'
import { templateDisplayName } from '../constants/policy.js'
import { generateUrl } from '@nextcloud/router'
import { showSuccess, showError, showWarning } from '@nextcloud/dialogs'
import axios from '@nextcloud/axios'
import { NcButton, NcLoadingIcon, NcTextField } from '@nextcloud/vue'
import AccountGroup    from 'vue-material-design-icons/AccountGroup.vue'
import AccountQuestion from 'vue-material-design-icons/AccountQuestion.vue'
import ExitToApp       from 'vue-material-design-icons/ExitToApp.vue'
import OpenInApp       from 'vue-material-design-icons/OpenInApp.vue'
import Plus            from 'vue-material-design-icons/Plus.vue'
import ViewGrid        from 'vue-material-design-icons/ViewGrid.vue'
import ViewList        from 'vue-material-design-icons/ViewList.vue'
import { ICON_BODY, ICON_HERO, ICON_XL } from '../constants/uiTokens.js'

export default {
    name: 'BrowseTeamsView',
    components: {
        NcButton,
        NcLoadingIcon,
        NcTextField,
        AccountGroup,
        AccountQuestion,
        ExitToApp,
        OpenInApp,
        Plus,
        ViewGrid,
        ViewList,
    },
    data() {
        return {
            ICON_BODY,
            ICON_HERO,
            ICON_XL,
            loading: false,
            teams: [],
            searchQuery: '',
            viewMode: 'grid',
            // Tracks which team ID has a pending action to prevent double-clicks.
            actionInProgress: {},
        }
    },
    computed: {
        filteredTeams() {
            if (!this.searchQuery) {
                return this.teams
            }
            const query = this.searchQuery.toLowerCase()
            return this.teams.filter(team => {
                const nameMatch  = team.name.toLowerCase().includes(query)
                const descMatch  = team.description?.toLowerCase().includes(query)
                // v4.0.9 — also match on the localized template badge so a
                // user browsing in Dutch can type "Samenwerking" and land on
                // every collaboration team. templateLabel returns '' for
                // legacy teams without a stored template — those simply skip
                // the label check and fall back to name/description matching.
                const labelMatch = this.templateLabel(team).toLowerCase().includes(query)
                return nameMatch || descMatch || labelMatch
            })
        },
    },
    mounted() {
        this.loadTeams()
    },
    methods: {
        t,

        /**
         * v4.0.2 — the badge, from `team.template` as the browse endpoint
         * sends it: { key, label, isSeeded }, or null for a legacy team with
         * no row, which shows no badge (the team-type fallback design).
         *
         * v4.13.28 — this was a four-arm `if` chain over the seeded keys, so
         * it was blind to `service` (shipped v4.10.23) and to every template
         * an administrator has been able to create since v4.13.24: both
         * rendered no badge at all. `templateDisplayName()` is the rule the
         * admin panels already use — a seeded template's label is translated
         * by key, an administrator's own label is shown as they wrote it.
         *
         * Returns '' rather than null so `filteredTeams` can match on it
         * without a guard.
         */
        templateLabel(team) {
            const tmpl = team?.template
            if (!tmpl?.key) return ''
            return templateDisplayName(tmpl.key, tmpl.label, tmpl.isSeeded)
        },
        templateTooltip(team) {
            const label = this.templateLabel(team)
            if (!label) return ''
            // TRANSLATORS: {template} is the name of the team template, e.g. "Collaboration"
            return t('teamhub', 'Created from the {template} template.', { template: label })
        },

        async loadTeams() {
            this.loading = true
            try {
                const response = await axios.get(generateUrl('/apps/teamhub/api/v1/teams/browse'))
                this.teams = response.data || []
            } catch (error) {
                showError(t('teamhub', 'Failed to load teams'))
            } finally {
                this.loading = false
            }
        },

        async joinTeam(team) {
            this.actionInProgress[team.id] = true
            try {
                await axios.post(generateUrl(`/apps/teamhub/api/v1/teams/${team.id}/join`), {})
                showSuccess(t('teamhub', 'You have joined {team}', { team: team.name }))
                team.isMember = true
                team.isDirectMember = true
                this.$emit('team-joined', team.id)
            } catch (error) {
                if (this.reportIfInviteOnly(error, team)) return
                showError(t('teamhub', 'Failed to join team'))
            } finally {
                this.actionInProgress[team.id] = false
            }
        },

        async requestAccess(team) {
            this.actionInProgress[team.id] = true
            try {
                await axios.post(generateUrl(`/apps/teamhub/api/v1/teams/${team.id}/join`), {})
                showSuccess(t('teamhub', 'Access requested for {team}', { team: team.name }))
                // Don't flip isMember — user is in Requesting state, not yet approved
            } catch (error) {
                if (this.reportIfInviteOnly(error, team)) return
                showError(t('teamhub', 'Failed to request access'))
            } finally {
                this.actionInProgress[team.id] = false
            }
        },

        /**
         * v4.6.17 — the team's join policy changed after this list was loaded.
         * Says so, and corrects the card in place so the button that cannot
         * work is replaced by the reason it cannot, without a full reload.
         *
         * @param {object} error axios error from the join endpoint
         * @param {object} team the card's team, mutated in place on a match
         * @return {boolean} true when handled — caller should not also report
         */
        reportIfInviteOnly(error, team) {
            if (error.response?.data?.error !== 'invite_only') {
                return false
            }
            showError(t('teamhub', '{team} is invite only. Ask a member of the team to invite you.', { team: team.name }))
            team.joinPolicy = 'closed'
            team.requiresApproval = false
            return true
        },

        openTeam(team) {
            this.$emit('team-opened', team.id)
        },

        async leaveTeam(team) {
            this.actionInProgress[team.id] = true
            try {
                const { data } = await axios.post(generateUrl(`/apps/teamhub/api/v1/teams/${team.id}/leave`), {})

                // v4.4.8 — a group or sub-team still grants access. The card
                // flips to the existing indirect-member state (Open + disabled
                // Leave + "via group" badge) rather than back to Join.
                if (data?.stillMember) {
                    showWarning(t('teamhub', 'You are no longer a direct member, but you still have access to this team through a group or another team.'))
                    team.isDirectMember = false
                    return
                }

                showSuccess(t('teamhub', 'You have left {team}', { team: team.name }))
                team.isMember = false
                team.isDirectMember = false
                this.$emit('team-left', team.id)
            } catch (error) {
                const msg = error.response?.data?.error || ''
                if (msg === 'indirect_member') {
                    showError(t('teamhub', 'You were added to this team through a group or another team. Ask your administrator to remove you.'))
                    return
                }
                showError(msg || t('teamhub', 'Failed to leave team'))
            } finally {
                this.actionInProgress[team.id] = false
            }
        },
    },
}
</script>

