<template>
    <NcModal
        :name="t('teamhub', 'Add task')"
        @close="$emit('close')">
        <div class="addtask-modal">
            <h3 class="addtask-modal__title">
                <CheckboxMarkedOutline :size="ICON_BODY" />
                {{ t('teamhub', 'Add task') }}
            </h3>

            <div class="addtask-modal__field">
                <NcTextField
                    v-model="form.title"
                    :label="t('teamhub', 'Task title')"
                    :placeholder="t('teamhub', 'e.g. Review design mockups')"
                    :error="!!errors.title"
                    :helper-text="errors.title || ''" />
            </div>

            <div class="addtask-modal__field">
                <NcTextArea
                    v-model="form.description"
                    :label="t('teamhub', 'Description (optional)')"
                    :placeholder="t('teamhub', 'More details about the task…')"
                    :rows="3" />
            </div>

            <div class="addtask-modal__row">
                <div class="addtask-modal__field">
                    <label class="addtask-modal__label">{{ t('teamhub', 'Due date (optional)') }}</label>
                    <input
                        v-model="form.dueDate"
                        type="date"
                        class="addtask-modal__input"
                        :min="todayDate" />
                </div>
                <div class="addtask-modal__field">
                    <label class="addtask-modal__label">{{ t('teamhub', 'Due time') }}</label>
                    <input
                        v-model="form.dueTime"
                        type="time"
                        class="addtask-modal__input"
                        :disabled="!form.dueDate" />
                </div>
            </div>

            <!-- Board picker — only shown when team has 2+ boards -->
            <div v-if="showBoardPicker" class="addtask-modal__field">
                <label class="addtask-modal__label">{{ t('teamhub', 'Board') }}</label>
                <div class="resource-inline-picker">
                    <NcButton
                        v-for="board in boards"
                        :key="board.board_id"
                        class="resource-inline-picker__item"
                        :class="{ 'resource-inline-picker__item--selected': activeBoardId === board.board_id }"
                        @click="selectedBoardId = board.board_id"
                        :pressed="activeBoardId === board.board_id"
                        variant="tertiary">
                        <span
                        v-if="board.color"
                        class="resource-inline-picker__color"
                        :style="{ background: board.color }"
                        aria-hidden="true" />
                        {{ board.name }}
                    </NcButton>
                </div>
            </div>

            <p v-if="errors.general" class="addtask-modal__error">{{ errors.general }}</p>

            <div class="addtask-modal__actions">
                <NcButton variant="primary" :disabled="saving" @click="submit">
                    <template #icon>
                        <NcLoadingIcon v-if="saving" :size="ICON_BODY" />
                        <CheckboxMarkedOutline v-else :size="ICON_BODY" />
                    </template>
                    {{ saving ? t('teamhub', 'Adding…') : t('teamhub', 'Add task') }}
                </NcButton>
                <NcButton variant="tertiary" @click="$emit('close')">
                    {{ t('teamhub', 'Cancel') }}
                </NcButton>
            </div>
        </div>
    </NcModal>
</template>

<script>
import { translate as t } from '@nextcloud/l10n'
import { generateUrl } from '@nextcloud/router'
import { showSuccess, showError } from '@nextcloud/dialogs'
import axios from '@nextcloud/axios'
import { NcModal, NcButton, NcLoadingIcon, NcTextField, NcTextArea } from '@nextcloud/vue'
import CheckboxMarkedOutline from 'vue-material-design-icons/CheckboxMarkedOutline.vue'
import { ICON_BODY } from '../constants/uiTokens.js'

export default {
    name: 'AddTaskModal',
    components: { NcModal, NcButton, NcLoadingIcon, NcTextField, NcTextArea, CheckboxMarkedOutline },
    props: {
        boards: { type: Array, default: () => [] }, // [{ board_id, name, color }]
    },
    emits: ['close', 'created'],
    data() {
        return {
            ICON_BODY,
            saving: false,
            errors: {},
            stacks: [],
            selectedBoardId: null,
            form: {
                title:       '',
                description: '',
                dueDate:     '',
                dueTime:     '09:00',
            },
        }
    },
    computed: {
        todayDate() {
            const n = new Date()
            const pad = v => String(v).padStart(2, '0')
            return `${n.getFullYear()}-${pad(n.getMonth()+1)}-${pad(n.getDate())}`
        },
        showBoardPicker() {
            return this.boards && this.boards.length > 1
        },
        activeBoardId() {
            return this.selectedBoardId ?? (this.boards[0]?.board_id ?? null)
        },
    },
    watch: {
        activeBoardId: {
            immediate: true,
            async handler(boardId) {
                if (!boardId) return
                try {
                    const { data } = await axios.get(
                        generateUrl(`/apps/deck/api/v1.0/boards/${boardId}/stacks`),
                        { headers: { 'OCS-APIRequest': 'true' } }
                    )
                    this.stacks = Array.isArray(data) ? data : []
                } catch (e) {
                    this.stacks = []
                }
            },
        },
    },
    async mounted() {},
    methods: {
        t,
        validate() {
            this.errors = {}
            if (!this.form.title.trim()) {
                this.errors.title = t('teamhub', 'Task title is required')
            }
            return Object.keys(this.errors).length === 0
        },
        async submit() {
            if (!this.validate()) return
            this.saving = true
            this.errors = {}

            if (this.stacks.length === 0) {
                this.errors.general = t('teamhub', 'No stack found on this board. Add a stack in Deck first.')
                this.saving = false
                return
            }

            const stackId = this.stacks[0].id
            const payload = { title: this.form.title.trim() }

            if (this.form.description.trim()) {
                payload.description = this.form.description.trim()
            }

            if (this.form.dueDate) {
                const dueIso = new Date(`${this.form.dueDate}T${this.form.dueTime}:00`).toISOString()
                payload.duedate = dueIso
            }

            try {
                const res = await axios.post(
                    generateUrl(`/apps/deck/api/v1.0/boards/${this.activeBoardId}/stacks/${stackId}/cards`),
                    payload,
                    { headers: { 'OCS-APIRequest': 'true' } }
                )
                showSuccess(t('teamhub', 'Task added'))
                // Session B: emit the created card info so callers can
                // capture the path for linking to a decision.
                const card = res?.data || {}
                this.$emit('created', {
                    boardId: this.activeBoardId,
                    stackId,
                    cardId: card.id || null,
                    title:  card.title || this.form.title.trim(),
                    path:   card.id ? `apps/deck/board/${this.activeBoardId}/card/${card.id}` : null,
                })
                this.$emit('close')
            } catch (e) {
                const msg = e?.response?.data?.message || ''
                this.errors.general = msg ? t('teamhub', 'Failed to add task: {error}', { error: msg }) : t('teamhub', 'Failed to add task')
                showError(t('teamhub', 'Failed to add task'))
            } finally {
                this.saving = false
            }
        },
    },
}
</script>

