<template>
    <!--
        TeamHub mobile single-canvas view.

        Shown only on viewports ≤ 768px (the parent TeamWidgetGrid decides).
        Replaces the desktop vue-grid-layout with one canvas that displays the
        message stream OR a single widget body, plus an icon bar at the bottom.

        State:
        - `activeWidget` (data) — which widget is currently shown in the canvas.
          Defaults to `'msgstream'`. Reset to `'msgstream'` on team switch.

        Layout:
        ┌─────────────────────┐
        │ Canvas (scrollable) │  ← message stream OR active widget
        ├─────────────────────┤
        │ Icon bar            │  ← Home + every available widget
        └─────────────────────┘
        Plus a FAB on message stream view only.
    -->
    <div class="teamhub-mobile-view">

        <!-- ── Canvas ───────────────────────────────────────────────── -->
        <!-- v4.13.26 — the canvas is a scroll container for every body that
             is as tall as its content, and a flex column for the one body
             that has no content height of its own: a blank-canvas widget's
             iframe. See the style block. -->
        <div
            class="teamhub-mobile-canvas"
            :class="{ 'teamhub-mobile-canvas--frame': activeWidgetIsFrame }">

            <!-- Active widget header (everything except message stream gets a title) -->
            <div v-if="activeWidget !== 'msgstream'" class="teamhub-mobile-widget-header">
                <component :is="activeWidgetMeta.icon" :size="ICON_BODY" />
                <h2 class="teamhub-mobile-widget-title">{{ activeWidgetMeta.title }}</h2>
            </div>

            <!-- ─── Message stream (default) ──────────────────────── -->
            <div v-show="activeWidget === 'msgstream'" class="teamhub-mobile-canvas-body">
                <MessageStream ref="messageStream" :hide-header="true" />
            </div>

            <!-- ─── Team Info ─────────────────────────────────────── -->
            <div v-if="activeWidget === 'widget-teaminfo'" class="teamhub-mobile-canvas-body teamhub-mobile-canvas-body--padded">
                <div class="teamhub-mobile-teaminfo">
                    <img
                        v-if="team.image_url"
                        :src="team.image_url"
                        :alt="team.name"
                        class="teamhub-mobile-teaminfo__logo" />
                    <p class="teamhub-mobile-teaminfo__description">
                        {{ team.description || t('teamhub', 'No description') }}
                    </p>
                    <div v-if="teamLabels.length" class="teamhub-mobile-teaminfo__labels" role="list" :aria-label="t('teamhub', 'Team type')">
                        <span
                            v-for="label in teamLabels"
                            :key="label.key"
                            :class="['teamhub-mobile-team-label', 'teamhub-mobile-team-label--' + label.tone]"
                            :title="label.tooltip"
                            role="listitem">
                            {{ label.text }}
                        </span>
                    </div>
                    <!-- v4.13.56 — team admins, not one owner. Same change as
                         the desktop Team info card; DESIGN §2.223. -->
                    <div v-if="teamAdmins.length" class="teamhub-mobile-teaminfo__owner">
                        <span class="teamhub-mobile-teaminfo__owner-label">{{ t('teamhub', 'Team admins') }}</span>
                        <div
                            v-for="admin in teamAdmins"
                            :key="admin.userId || admin.displayName"
                            class="teamhub-mobile-teaminfo__owner-row">
                            <NcAvatar
                                v-if="admin.userId"
                                :user="admin.userId"
                                :display-name="admin.displayName"
                                :hide-status="true"
                                :size="32" />
                            <span>{{ admin.displayName }}</span>
                        </div>
                    </div>
                </div>
            </div>

            <!-- ─── Members ───────────────────────────────────────── -->
            <div v-if="activeWidget === 'widget-members'" class="teamhub-mobile-canvas-body teamhub-mobile-canvas-body--notoppad">
                <MembersWidget @view-presence-calendar="$emit('set-view', 'presence')" />
            </div>

            <!-- ─── Birthdays — Department teams only ─────────────── -->
            <div v-if="activeWidget === 'widget-birthdays'" class="teamhub-mobile-canvas-body">
                <BirthdaysWidget />
            </div>

            <!-- ─── Calendar ──────────────────────────────────────── -->
            <div v-if="activeWidget === 'widget-calendar'" class="teamhub-mobile-canvas-body">
                <CalendarWidget ref="calendarWidget" />
            </div>

            <!-- ─── Tasks ─────────────────────────────────────────── -->
            <div v-if="activeWidget === 'widget-deck'" class="teamhub-mobile-canvas-body">
                <DeckWidget ref="deckWidget" @openproject-actions="openProjectWorkActions = $event"
                    @edit-openproject-work-package="$emit('edit-openproject-work-package', $event)" />
            </div>

            <!-- ─── Activity ──────────────────────────────────────── -->
            <div v-if="activeWidget === 'widget-activity'" class="teamhub-mobile-canvas-body">
                <ActivityWidget @show-more="$emit('set-view', 'activity')" />
            </div>

            <!-- ─── Pages (Intranet + Wiki, unified v4.3.7) ───────── -->
            <div v-if="activeWidget === 'widget-pages'" class="teamhub-mobile-canvas-body">
                <IntravoxWidget
                    ref="intravoxWidget"
                    :can-act="isTeamModerator"
                    @pages-loaded="$emit('pages-loaded', $event)"
                    @collective-loaded="$emit('collective-loaded', $event)" />
            </div>

            <!-- ─── File Center (tabbed: Favourites / Recent / Shared) ── -->
            <div v-if="activeWidget === 'widget-files-center'" class="teamhub-mobile-canvas-body teamhub-mobile-canvas-body--notoppad">
                <FilesWidget />
            </div>

            <div v-if="activeWidget === 'widget-decisions'" class="teamhub-mobile-canvas-body teamhub-mobile-canvas-body--notoppad">
                <DecisionsWidget />
            </div>

            <!-- v3.97.0 — Project Health widget on mobile -->
            <div v-if="activeWidget === 'widget-project-health'" class="teamhub-mobile-canvas-body teamhub-mobile-canvas-body--notoppad">
                <ProjectHealthWidget @open-tab="$emit('set-view', $event)" />
            </div>

            <!-- v4.9.3 — Project info on mobile. Its links into OpenProject
                 come through `actions` and feed the FAB (v4.9.5). -->
            <div v-if="activeWidget === 'widget-openproject'" class="teamhub-mobile-canvas-body teamhub-mobile-canvas-body--notoppad">
                <OpenProjectOverviewWidget ref="openProjectWidget" @actions="openProjectActions = $event" />
            </div>

            <!-- v4.10.27 — the service team's queue and statistics on mobile. -->
            <div v-if="activeWidget === 'widget-service-queue'" class="teamhub-mobile-canvas-body teamhub-mobile-canvas-body--notoppad">
                <ServiceQueueWidget />
            </div>
            <div v-if="activeWidget === 'widget-service-stats'" class="teamhub-mobile-canvas-body teamhub-mobile-canvas-body--notoppad">
                <ServiceStatsWidget />
            </div>
            <!-- v4.10.50 — teams made outside TeamHub on mobile. -->
            <div v-if="activeWidget === 'widget-team-adoption'" class="teamhub-mobile-canvas-body">
                <TeamAdoptionGrid compact />
            </div>

            <!-- ─── External integration widgets ──────────────────── -->
            <template v-for="ext in teamWidgets">
                <div
                    v-if="activeWidget === 'widget-int-' + ext.registry_id"
                    :key="'mobile-int-' + ext.registry_id"
                    class="teamhub-mobile-canvas-body">
                    <IntegrationWidget
                        :integration="ext"
                        :team-id="currentTeamId"
                        @actions-loaded="$emit('widget-actions-loaded', $event)" />
                </div>
            </template>

            <!-- ─── Integration-package widgets (v4.13.24) ─────────── -->
            <template v-for="cap in packageWidgets">
                <div
                    v-if="activeWidget === 'widget-int-cap-' + cap.cap_id"
                    :key="'mobile-int-cap-' + cap.cap_id"
                    class="teamhub-mobile-canvas-body"
                    :class="{ 'teamhub-mobile-canvas-body--frame': isCanvasCapability(cap) }">
                    <!-- A blank-canvas capability draws its own body; a row
                         one gets the list. Same split as the desktop grid,
                         and since v4.13.26 the same shared test. -->
                    <IntegrationCanvasWidget
                        v-if="isCanvasCapability(cap)"
                        :integration="cap" />
                    <IntegrationWidget
                        v-else
                        :integration="cap"
                        :team-id="currentTeamId"
                        @actions-loaded="$emit('widget-actions-loaded', $event)" />
                </div>
            </template>
        </div>

        <!--
            Action FAB. Behaviour depends on the active widget's action set:
              0 actions → not rendered
              1 action  → tap fires the action directly
              2+ actions → tap toggles a small sheet listing each action

            One <button> handles both cases for visual consistency. The sheet
            is a sibling element controlled by `actionsMenuOpen` state and
            dismissed by:
              • tapping any action
              • tapping the backdrop
              • pressing Escape
        -->
        <button
            v-if="currentActions.length > 0"
            ref="fab"
            class="teamhub-mobile-fab"
            :class="{ 'teamhub-mobile-fab--active': actionsMenuOpen }"
            type="button"
            :disabled="currentActions.length === 1 && !!currentActions[0].disabled"
            :aria-label="fabAriaLabel"
            :aria-haspopup="currentActions.length > 1 ? 'menu' : null"
            :aria-expanded="currentActions.length > 1 ? String(actionsMenuOpen) : null"
            :title="fabTitle"
            @click="onFabClick">
            <Plus :size="ICON_LARGE" />
        </button>

        <!-- Backdrop + sheet for the multi-action menu -->
        <div
            v-if="actionsMenuOpen && currentActions.length > 1"
            class="teamhub-mobile-fab-backdrop"
            @click="closeActionsMenu" />

        <div
            v-if="actionsMenuOpen && currentActions.length > 1"
            class="teamhub-mobile-fab-sheet"
            role="menu"
            :aria-label="t('teamhub', 'Widget actions')"
            @keydown.esc.stop="closeActionsMenu">
            <button
                v-for="action in currentActions"
                :key="action.key"
                role="menuitem"
                type="button"
                class="teamhub-mobile-fab-sheet__item"
                :disabled="!!action.disabled"
                :title="action.disabled && action.disabledTitle ? action.disabledTitle : ''"
                @click="onSheetItemClick(action)">
                <component :is="action.icon" :size="ICON_BODY" />
                <span class="teamhub-mobile-fab-sheet__label">{{ action.label }}</span>
            </button>
        </div>

        <!-- ── Icon bar ────────────────────────────────────────────── -->
        <nav
            class="teamhub-mobile-icon-bar"
            role="tablist"
            :aria-label="t('teamhub', 'Widgets')">
            <button
                v-for="item in availableWidgets"
                :key="item.key"
                role="tab"
                type="button"
                class="teamhub-mobile-icon-bar__item"
                :class="{ 'teamhub-mobile-icon-bar__item--active': activeWidget === item.key }"
                :aria-selected="activeWidget === item.key ? 'true' : 'false'"
                :aria-label="item.title"
                :title="item.title"
                @click="setActive(item.key)">
                <component :is="item.icon" :size="ICON_BODY" />
                <span class="teamhub-mobile-icon-bar__label">{{ item.shortTitle || item.title }}</span>
            </button>
        </nav>
    </div>
</template>

<script>
import { mapState, mapGetters } from 'vuex'
import { translate as t, translatePlural as n } from '@nextcloud/l10n'
import { NcAvatar, NcButton } from '@nextcloud/vue'
import { ICON_BODY, ICON_LARGE } from '../constants/uiTokens.js'
import { isCanvasCapability } from '../lib/activeWidgets.js'

import MessageOutline from 'vue-material-design-icons/MessageOutline.vue'
import InformationOutline from 'vue-material-design-icons/InformationOutline.vue'
import AccountGroup from 'vue-material-design-icons/AccountGroup.vue'
import AccountPlus from 'vue-material-design-icons/AccountPlus.vue'
import Calendar from 'vue-material-design-icons/Calendar.vue'
import CalendarPlus from 'vue-material-design-icons/CalendarPlus.vue'
import CardText from 'vue-material-design-icons/CardText.vue'
import CheckboxMarkedOutline from 'vue-material-design-icons/CheckboxMarkedOutline.vue'
import GavelIcon from 'vue-material-design-icons/Gavel.vue'
import ClipboardPlusOutline from 'vue-material-design-icons/ClipboardPlusOutline.vue'
import ClockOutline from 'vue-material-design-icons/ClockOutline.vue'
import Cog from 'vue-material-design-icons/Cog.vue'
import ContentCopy from 'vue-material-design-icons/ContentCopy.vue'
import FileDocumentOutline from 'vue-material-design-icons/FileDocumentOutline.vue'
import FilePlus from 'vue-material-design-icons/FilePlus.vue'
import Folder from 'vue-material-design-icons/Folder.vue'
import LocationExit from 'vue-material-design-icons/LocationExit.vue'
import Plus from 'vue-material-design-icons/Plus.vue'
import Puzzle from 'vue-material-design-icons/Puzzle.vue'
import TrashCan from 'vue-material-design-icons/TrashCan.vue'
import VideoIcon from 'vue-material-design-icons/Video.vue'

import MessageStream from './MessageStream.vue'
import CalendarWidget from './CalendarWidget.vue'
import DeckWidget from './DeckWidget.vue'
import ActivityWidget from './ActivityWidget.vue'
import IntravoxWidget from './IntravoxWidget.vue'
import IntegrationWidget from './IntegrationWidget.vue'
import IntegrationCanvasWidget from './IntegrationCanvasWidget.vue'
import FilesWidget          from './FilesWidget.vue'
import DecisionsWidget      from './DecisionsWidget.vue'
import MembersWidget        from './MembersWidget.vue'
import BirthdaysWidget from './BirthdaysWidget.vue'
import CakeVariant from 'vue-material-design-icons/CakeVariant.vue'
import ProjectHealthWidget  from './ProjectHealthWidget.vue'
import ViewDashboard        from 'vue-material-design-icons/ViewDashboard.vue'
// v4.9.3 — OpenProject Phase 1: the Project info widget and (v4.9.5) the
// icons of its FAB actions.
import OpenProjectOverviewWidget from './OpenProjectOverviewWidget.vue'
import BriefcaseOutline          from 'vue-material-design-icons/BriefcaseOutline.vue'
import OpenInNew                 from 'vue-material-design-icons/OpenInNew.vue'
import FormatListChecks          from 'vue-material-design-icons/FormatListChecks.vue'
import PlusBoxOutline            from 'vue-material-design-icons/PlusBoxOutline.vue'
import FolderOutline             from 'vue-material-design-icons/FolderOutline.vue'
import Refresh                   from 'vue-material-design-icons/Refresh.vue'
import LifebuoyIcon              from 'vue-material-design-icons/Lifebuoy.vue'
import ChartBoxOutline           from 'vue-material-design-icons/ChartBoxOutline.vue'
import ServiceQueueWidget        from './ServiceQueueWidget.vue'
import ServiceStatsWidget        from './ServiceStatsWidget.vue'
import TeamAdoptionGrid          from './admin/TeamAdoptionGrid.vue'
import AccountMultipleCheckOutline from 'vue-material-design-icons/AccountMultipleCheckOutline.vue'

export default {
    name: 'MobileWidgetView',

    components: {
        NcAvatar, NcButton,
        // icons used in the icon bar / canvas headers — registered here so
        // <component :is="..."> resolves them
        MessageOutline, InformationOutline, AccountGroup, CakeVariant, BirthdaysWidget,
        AccountPlus, Calendar, CalendarPlus, CardText, CheckboxMarkedOutline, GavelIcon,
        ClipboardPlusOutline, ClockOutline, Cog, ContentCopy,
        FileDocumentOutline, FilePlus, Folder, LocationExit, Plus, Puzzle,
        TrashCan, VideoIcon, ViewDashboard, BriefcaseOutline,
        OpenInNew, FormatListChecks, PlusBoxOutline, FolderOutline, Refresh,
        LifebuoyIcon, ChartBoxOutline,
        // widget bodies
        MessageStream, CalendarWidget, DeckWidget, ActivityWidget,
        IntravoxWidget, IntegrationWidget, IntegrationCanvasWidget,
        FilesWidget, DecisionsWidget, MembersWidget,
        ProjectHealthWidget,
        OpenProjectOverviewWidget,
        ServiceQueueWidget, ServiceStatsWidget,
        TeamAdoptionGrid, AccountMultipleCheckOutline,
    },

    props: {
        // Data needed to render the team-info widget
        teamLabels:   { type: Array,  default: () => [] },
        /**
         * v4.13.56 — the team's admins, level 9 first. Was `teamOwner`, one
         * object. TeamWidgetGrid computes it; this view only renders it.
         */
        teamAdmins:   { type: Array, default: () => [] },
        isTeamAdmin:  { type: Boolean, default: false },
        isTeamModerator: { type: Boolean, default: false },
        // Whether to show the Tasks widget at all (Deck OR Tasks resource)
        showTasksWidget: { type: Boolean, default: false },
        // Pages widget data
        pagesData: { type: Object, default: () => ({ teamPage: null, subPages: [], teamhubRoot: null, allPages: [] }) },
    },

    emits: [
        'manage-team', 'copy-link', 'invite', 'leave-team',
        'schedule-meeting', 'add-event', 'add-meeting',
        'add-deck-task', 'add-personal-task', 'add-openproject-work-package',
        // v4.13.9 - `{ workPackageId }` from a row's pencil.
        'edit-openproject-work-package',
        'create-page', 'delete-page', 'create-wiki-page', 'pages-loaded', 'collective-loaded',
        'set-view',
        'widget-actions-loaded',
    ],

    data() {
        return {
            ICON_BODY,
            ICON_LARGE,
            activeWidget: 'msgstream',
            // Open/closed state for the multi-action FAB sheet. Reset to
            // false whenever the active widget changes (a stale-open menu
            // from a previous widget would otherwise show wrong actions).
            actionsMenuOpen: false,
            // v4.9.5 — the Project info widget's links, as it reports them.
            openProjectActions: { projectUrl: null, workPackagesUrl: null, newWorkPackageUrl: null, filesUrl: null },
            // v4.9.15 — the Upcoming tasks widget's report of the viewer's
            // OpenProject rights; the FAB's create item shows when true.
            openProjectWorkActions: { canCreate: false },
        }
    },

    computed: {
        ...mapState([
            'currentTeamId', 'resources', 'teamType',
            // v4.13.24 — `packageWidgets` joins `teamWidgets`: the two
            // registries are separate mechanisms and a team can have either.
            'teamWidgets', 'packageWidgets', 'isCurrentUserDirectMember',
            'decisionsModuleEnabled', 'decisionsConfig',
            // v3.104.1 — drops msgstream from the icon bar / canvas when
            // Messages is off for the team.
            'messagesConfig', 'presenceModuleEnabled', 'presenceConfig',
            // v4.3.5 — Wiki (Collectives) toggle. Contributes to the
            // widget-pages icon-bar gate (widget renders when EITHER
            // Intranet or Wiki is enabled). Kept in mapState so the
            // reactive gate re-evaluates when the toggle flips.
            'collectivesConfig',
            // Team-wide dashboard customization — hidden_widgets also drops
            // widgets from the mobile icon bar so mobile matches desktop.
            'dashboardConfig',
            // v3.97.0 — same gate as TeamWidgetGrid for the Project Health widget.
            'budgetConfig', 'timeConfig', 'project',
            // v4.9.3 — same gate as TeamWidgetGrid for the OpenProject widgets.
            'openProjectConfig',
            // v4.10.27 — same gate as TeamWidgetGrid for the service desk widgets.
            'serviceDeskConfig',
        ]),
        ...mapGetters(['currentTeam']),

        team() { return this.currentTeam || {} },

        /**
         * v4.13.26 — whether the widget on screen is a blank canvas, i.e. an
         * iframe whose height has to come from this view rather than from its
         * own content. Only a package capability can be one.
         *
         * @return {boolean}
         */
        activeWidgetIsFrame() {
            if (!this.activeWidget.startsWith('widget-int-cap-')) return false
            const capId = this.activeWidget.slice('widget-int-cap-'.length)
            const cap = (this.packageWidgets || [])
                .find(w => String(w.cap_id) === capId)
            return isCanvasCapability(cap)
        },

        /**
         * v3.104.1 — per-team Messages toggle. Default true so a team that
         * never touches the setting keeps its stream + FAB.
         */
        messagesEnabled() {
            return this.messagesConfig?.messages_enabled !== false
        },

        /**
         * The full list of widgets the current user has access to.
         *
         * Mirrors the same v-if gates the desktop grid uses, so "available"
         * here means exactly what the desktop layout shows. Missing
         * resources => widget is hidden from the icon bar.
         *
         * Order is fixed (not user-orderable on mobile in v1).
         */
        availableWidgets() {
            const list = []

            // Home / message stream — first when the team has Messages on.
            // v3.104.1: teams that disable Messages skip this entry entirely
            // and land on Team info as the default canvas.
            if (this.messagesEnabled) {
                list.push({
                    key: 'msgstream',
                    title: t('teamhub', 'Messages'),
                    shortTitle: t('teamhub', 'Home'),
                    icon: 'MessageOutline',
                })
            }

            list.push({
                key: 'widget-teaminfo',
                title: t('teamhub', 'Team info'),
                shortTitle: t('teamhub', 'Info'),
                icon: 'InformationOutline',
            })

            if (this.teamType === 'department' && this.presenceModuleEnabled
                && this.presenceConfig?.presence_enabled) {
                list.push({ key: 'widget-birthdays', title: t('teamhub', 'Birthdays'), icon: 'CakeVariant' })
            }

            list.push({
                key: 'widget-members',
                title: t('teamhub', 'Members'),
                icon: 'AccountGroup',
            })

            if (this.resources.calendar) {
                list.push({
                    key: 'widget-calendar',
                    title: t('teamhub', 'Upcoming events'),
                    shortTitle: t('teamhub', 'Events'),
                    icon: 'Calendar',
                })
            }

            if (this.showTasksWidget) {
                list.push({
                    key: 'widget-deck',
                    title: t('teamhub', 'Upcoming tasks'),
                    shortTitle: t('teamhub', 'Tasks'),
                    icon: 'CardText',
                })
            }

            list.push({
                key: 'widget-activity',
                title: t('teamhub', 'Team activity'),
                shortTitle: t('teamhub', 'Activity'),
                icon: 'ClockOutline',
            })

            // v4.3.7 — unified Pages widget: shown when EITHER provider
            // is active. IntravoxWidget renders both sections internally.
            if (this.resources.intravox || this.collectivesConfig?.collectives_enabled) {
                list.push({
                    key: 'widget-pages',
                    title: t('teamhub', 'Pages'),
                    icon: 'FileDocumentOutline',
                })
            }

            if (this.resources.files) {
                list.push({
                    key: 'widget-files-center',
                    title: t('teamhub', 'File center'),
                    shortTitle: t('teamhub', 'Files'),
                    icon: 'Folder',
                })
            }

            if (this.decisionsModuleEnabled && this.decisionsConfig && this.decisionsConfig.decisions_enabled) {
                list.push({
                    key: 'widget-decisions',
                    // TRANSLATORS: mobile navigation label for the Decisions widget
                    title: t('teamhub', 'Decisions'),
                    icon: 'GavelIcon',
                })
            }

            // v3.97.0 — Project Health widget. Same gate as TeamWidgetGrid.
            // Planning included so admins see the widget during setup, not
            // only once execution starts.
            if (this.project?.isProject
                && this.project?.mode === 'advanced'
                && (this.project?.phase === 'planning' || this.project?.phase === 'execution')
                && this.budgetConfig?.can_view_budget
                && this.timeConfig?.can_view_time) {
                list.push({
                    key: 'widget-project-health',
                    // TRANSLATORS: mobile navigation label for the Project health widget
                    title: t('teamhub', 'Project health'),
                    icon: 'ViewDashboard',
                })
            }

            // v4.9.3 — the Project info widget. Same gate as TeamWidgetGrid.
            if (this.openProjectConfig?.eligible && this.openProjectConfig?.linked) {
                list.push({
                    key: 'widget-openproject',
                    // TRANSLATORS: mobile navigation label for the linked OpenProject project's overview widget
                    title: t('teamhub', 'Project info'),
                    shortTitle: t('teamhub', 'Project'),
                    icon: 'BriefcaseOutline',
                })
            }

            // v4.10.27 — the service team's queue and statistics. Same gate
            // as TeamWidgetGrid (src/lib/activeWidgets.js).
            if (this.serviceDeskConfig?.isDesk) {
                list.push({
                    key: 'widget-service-queue',
                    // TRANSLATORS: mobile navigation label for a service team's request queue widget
                    title: t('teamhub', 'Service requests'),
                    shortTitle: t('teamhub', 'Requests'),
                    icon: 'LifebuoyIcon',
                })
                list.push({
                    key: 'widget-service-stats',
                    // TRANSLATORS: mobile navigation label for a service team's request statistics widget
                    title: t('teamhub', 'Statistics'),
                    shortTitle: t('teamhub', 'Statistics'),
                    icon: 'ChartBoxOutline',
                })
            }

            // v4.10.50 — same gate as TeamWidgetGrid (src/lib/activeWidgets.js).
            if (this.serviceDeskConfig?.handlesAdoption) {
                list.push({
                    key: 'widget-team-adoption',
                    // TRANSLATORS: mobile navigation label for the grid where teams made outside TeamHub are accepted or declined
                    title: t('teamhub', 'Teams made outside TeamHub'),
                    // TRANSLATORS: short mobile navigation label for the grid of teams made outside TeamHub
                    shortTitle: t('teamhub', 'New teams'),
                    icon: 'AccountMultipleCheckOutline',
                })
            }

            // v4.10.44 — the retired Services widget (v4.10.34) is the
            // Services tab now.

            // External integration widgets — registry-driven. Use the same
            // generic Puzzle icon as the canvas header and built-in widget
            // icons. App icon URLs can fail or be unavailable; hiding a broken
            // image previously left a text-only entry in this mobile bar.
            ;(this.teamWidgets || []).forEach(w => {
                list.push({
                    key: 'widget-int-' + w.registry_id,
                    title: w.title || t('teamhub', 'Widget'),
                    shortTitle: w.title || t('teamhub', 'Widget'),
                    icon: 'Puzzle',
                })
            })

            // v4.13.24 — integration-package widgets (v4.13.23). Same id
            // convention as the desktop grid (`widget-int-cap-<cap_id>`), so a
            // widget a team hid, moved or collapsed reads the same on both
            // surfaces. Mobile had no package path at all until now: a team
            // whose only widget came from a package got an icon bar that never
            // mentioned it.
            ;(this.packageWidgets || []).forEach(w => {
                list.push({
                    key: 'widget-int-cap-' + w.cap_id,
                    title: w.title || t('teamhub', 'Widget'),
                    shortTitle: w.title || t('teamhub', 'Widget'),
                    icon: 'Puzzle',
                })
            })

            // Team-wide owner/admin hidden widgets — drop them from the mobile
            // icon bar too so mobile matches the desktop dashboard.
            const hidden = this.dashboardConfig?.hidden_widgets || []
            return hidden.length ? list.filter(item => !hidden.includes(item.key)) : list
        },

        /**
         * The list of actions for the currently active widget.
         *
         * Each action is a plain object:
         *   {
         *     key:           string  — stable identity for v-for
         *     label:         string  — translated, shown in tooltip + menu
         *     icon:          string  — registered component name (e.g. 'Plus')
         *     handler:       Function (called from invokeAction)
         *     disabled:      boolean (optional)
         *     disabledTitle: string  (optional, tooltip while disabled)
         *   }
         *
         * Empty list ⇒ no FAB rendered.
         * One entry  ⇒ FAB fires it directly on tap.
         * Two+       ⇒ FAB opens a custom action sheet listing them.
         *
         * Gating mirrors the desktop grid exactly — same isTeamAdmin /
         * resources.* / isTeamModerator checks, so the user sees on mobile
         * exactly the actions they would have access to on desktop.
         */
        currentActions() {
            switch (this.activeWidget) {
                case 'msgstream':
                    return [{
                        key: 'post-message',
                        label: t('teamhub', 'Post message'),
                        icon: 'Plus',
                        handler: () => {
                            const stream = this.$refs.messageStream
                            if (stream && typeof stream.openPostForm === 'function') {
                                stream.openPostForm()
                            }
                        },
                    }]

                case 'widget-teaminfo': {
                    const actions = [
                        {
                            key: 'copy-link',
                            label: t('teamhub', 'Copy team link'),
                            icon: 'ContentCopy',
                            handler: () => this.$emit('copy-link'),
                        },
                    ]
                    if (this.isTeamModerator) {
                        actions.push({
                            key: 'invite',
                            label: t('teamhub', 'Invite user'),
                            icon: 'AccountPlus',
                            handler: () => this.$emit('invite'),
                        })
                    }
                    if (this.isTeamAdmin) {
                        actions.push({
                            key: 'manage-team',
                            label: t('teamhub', 'Manage team'),
                            icon: 'Cog',
                            handler: () => this.$emit('manage-team'),
                        })
                    }
                    actions.push({
                        key: 'leave-team',
                        label: t('teamhub', 'Leave team'),
                        icon: 'LocationExit',
                        disabled: !this.isCurrentUserDirectMember,
                        disabledTitle: this.isCurrentUserDirectMember
                            ? ''
                            : t('teamhub', 'You were added via a group or team. Ask your administrator to remove you.'),
                        handler: () => {
                            if (this.isCurrentUserDirectMember) {
                                this.$emit('leave-team')
                            }
                        },
                    })
                    return actions
                }

                case 'widget-members':
                    if (!this.isTeamModerator) return []
                    return [{
                        key: 'invite-members',
                        label: t('teamhub', 'Invite members'),
                        icon: 'AccountPlus',
                        handler: () => this.$emit('invite'),
                    }]

                case 'widget-calendar':
                    return [
                        {
                            key: 'add-event',
                            label: t('teamhub', 'Add event'),
                            icon: 'CalendarPlus',
                            handler: () => this.$emit('add-event'),
                        },
                        {
                            key: 'add-meeting',
                            label: t('teamhub', 'Add meeting'),
                            icon: 'AccountGroup',
                            handler: () => this.$emit('add-meeting'),
                        },
                    ]

                case 'widget-deck': {
                    const actions = []
                    if (this.resources.deck) {
                        actions.push({
                            key: 'add-deck-task',
                            label: t('teamhub', 'Create Deck task'),
                            icon: 'CheckboxMarkedOutline',
                            handler: () => this.$emit('add-deck-task'),
                        })
                    }
                    if (this.resources.tasks && this.resources.calendar) {
                        actions.push({
                            key: 'add-personal-task',
                            label: t('teamhub', 'Create personal task'),
                            icon: 'ClipboardPlusOutline',
                            handler: () => this.$emit('add-personal-task'),
                        })
                    }
                    // v4.9.15 — only when OpenProject grants "add work
                    // packages" to this viewer, as the widget reported.
                    if (this.openProjectWorkActions.canCreate) {
                        actions.push({
                            key: 'add-openproject-work-package',
                            label: t('teamhub', 'Create work package'),
                            icon: 'BriefcaseOutline',
                            handler: () => this.$emit('add-openproject-work-package'),
                        })
                    }
                    return actions
                }

                // v4.9.5 — the Project info widget's links into OpenProject,
                // the same set the desktop header menu offers, from the same
                // event. Each opens a new tab: OpenProject refuses to be
                // framed, and every OpenProject hand-off in TeamHub does this.
                case 'widget-openproject': {
                    const links = [
                        ['open-project',     this.openProjectActions.projectUrl,        t('teamhub', 'Open project'),     'OpenInNew'],
                        ['work-packages',    this.openProjectActions.workPackagesUrl,   t('teamhub', 'Work packages'),    'FormatListChecks'],
                        ['new-work-package', this.openProjectActions.newWorkPackageUrl, t('teamhub', 'New work package'), 'PlusBoxOutline'],
                        ['project-files',    this.openProjectActions.filesUrl,          t('teamhub', 'Project files'),    'FolderOutline'],
                    ]
                    const actions = links
                        .filter(([, url]) => !!url)
                        .map(([key, url, label, icon]) => ({
                            key, label, icon,
                            handler: () => window.open(url, '_blank', 'noopener,noreferrer'),
                        }))
                    actions.push({
                        key: 'refresh-openproject',
                        label: t('teamhub', 'Refresh project data'),
                        icon: 'Refresh',
                        handler: () => {
                            const widget = this.$refs.openProjectWidget
                            if (widget && typeof widget.refresh === 'function') widget.refresh()
                        },
                    })
                    return actions
                }

                case 'widget-pages': {
                    if (!this.isTeamModerator) return []
                    const actions = []
                    // v4.13.62 — the two Intranet actions are a team admin's,
                    // which is the gate their endpoints have always had; they
                    // were offered to moderators and refused. The reasoning is
                    // on the desktop grid (TeamWidgetGrid). *Create Collectives
                    // page* below stays a moderator's.
                    if (this.isTeamAdmin && this.resources.intravox) {
                        actions.push({
                            key: 'create-page',
                            label: t('teamhub', 'Create Intranet page'),
                            icon: 'FilePlus',
                            handler: () => this.$emit('create-page'),
                        })
                        actions.push({
                            key: 'delete-page',
                            label: t('teamhub', 'Delete Intranet page'),
                            icon: 'TrashCan',
                            disabled: !this.pagesData.teamPage,
                            handler: () => {
                                if (this.pagesData.teamPage) {
                                    this.$emit('delete-page')
                                }
                            },
                        })
                    }
                    if (this.collectivesConfig?.collectives_enabled) {
                        actions.push({
                            key: 'create-wiki-page',
                            label: t('teamhub', 'Create Collectives page'),
                            icon: 'FilePlus',
                            handler: () => this.$emit('create-wiki-page'),
                        })
                    }
                    return actions
                }

                // Widgets without actions: activity, files-*, integration widgets.
                // (Integration widgets may register dynamic actions per registry_id,
                //  but those are already surfaced via the desktop NcActions menu inside
                //  the widget body and don't have a clean handler shape on mobile yet.)
                default:
                    return []
            }
        },

        /**
         * Metadata for whichever widget is currently active.
         * Used to render the canvas-top title bar (icon + title) for any
         * widget except the message stream.
         */
        activeWidgetMeta() {
            return this.availableWidgets.find(w => w.key === this.activeWidget) || { title: '', icon: 'MessageOutline' }
        },

        /**
         * Accessible label for the FAB.
         * - 1 action: the action's label is the most informative thing.
         * - 2+ actions: a generic "actions menu" label, since the FAB is
         *   really a menu trigger at that point.
         */
        fabAriaLabel() {
            if (this.currentActions.length === 1) {
                return this.currentActions[0].label
            }
            return t('teamhub', 'Widget actions')
        },

        /**
         * Tooltip title for the FAB. Shows the disabled-reason when the
         * action is disabled (single-action case only).
         */
        fabTitle() {
            if (this.currentActions.length === 1) {
                const a = this.currentActions[0]
                if (a.disabled && a.disabledTitle) return a.disabledTitle
                return a.label
            }
            return t('teamhub', 'Widget actions')
        },
    },

    watch: {
        /**
         * Reset to message stream whenever the team switches, so we never
         * land on a stale widget that may not exist in the new team.
         */
        currentTeamId() {
            // v3.104.1 — Messages may be disabled for the new team; land on
            // the first available widget (msgstream when present, otherwise
            // typically Team info) instead of a blank canvas.
            this.activeWidget = this.availableWidgets[0]?.key || 'msgstream'
            this.actionsMenuOpen = false
        },

        /**
         * Whenever the active widget changes, close any open action sheet —
         * its contents would otherwise belong to the previous widget.
         */
        activeWidget() {
            this.actionsMenuOpen = false
        },

        /**
         * If the active widget becomes unavailable (e.g. an integration was
         * unregistered, or a resource was disabled), fall back to the first
         * widget in the list — historically that's always msgstream, but
         * v3.104.1 teams with Messages disabled land on the next available
         * widget (typically Team info) instead of an empty canvas.
         *
         * immediate:true covers the cold-mount case where messagesConfig is
         * already in the store and msgstream is absent from the very first
         * availableWidgets — without this, the default 'msgstream' would
         * render an empty stream body until the next store change.
         */
        availableWidgets: {
            immediate: true,
            handler(newList) {
                if (!newList.find(w => w.key === this.activeWidget)) {
                    this.activeWidget = newList[0]?.key || 'msgstream'
                }
            },
        },
    },

    methods: {
        t,
        n,
        // v4.13.26 — the shared frame test, used twice in the template: once
        // to pick the body component, once to give that body a height.
        isCanvasCapability,

        setActive(key) {
            if (this.activeWidget === key) return
            this.activeWidget = key
            // Scroll the new canvas to the top — otherwise the previous
            // widget's scroll offset bleeds through and looks like a render glitch.
            this.$nextTick(() => {
                const canvas = this.$el?.querySelector('.teamhub-mobile-canvas')
                if (canvas) canvas.scrollTop = 0
            })
        },

        /**
         * FAB click handler. Branches on action count:
         *   1 action  → fire it directly
         *   2+ actions → toggle the sheet open/closed
         */
        onFabClick() {
            if (this.currentActions.length === 1) {
                this.invokeAction(this.currentActions[0])
            } else if (this.currentActions.length > 1) {
                this.actionsMenuOpen = !this.actionsMenuOpen
            }
        },

        /**
         * Sheet item handler — fires the action then dismisses the sheet.
         * Disabled items are no-ops but still close the sheet for tap-feedback
         * consistency? No — leave the sheet open if the tap was a no-op so
         * the user can choose a different one.
         */
        onSheetItemClick(action) {
            if (!action || action.disabled) return
            this.invokeAction(action)
            this.closeActionsMenu()
        },

        /**
         * Close the sheet. Called from the backdrop tap, sheet item taps,
         * Escape keypress, and (defensively) when the active widget changes.
         */
        closeActionsMenu() {
            this.actionsMenuOpen = false
        },

        /**
         * Fire a single action object (from currentActions). Honours the
         * `disabled` flag — disabled actions still get rendered with a
         * tooltip explaining why, but tapping them is a no-op.
         */
        invokeAction(action) {
            if (!action) return
            if (action.disabled) return
            if (typeof action.handler === 'function') {
                action.handler()
            }
        },

    },
}
</script>

