        'create-page', 'delete-page', 'create-wiki-page', 'pages-loaded', 'collective-loaded', 'set-view',
        'widget-actions-loaded',
        'set-as-default',
        'reset-to-default',
        'propose-decision',
    ],

    data() {
        return {
            // v4.13.34 — this viewer has waved away the team's suggested
