         * v4.11.42 — somebody outside this view asked for the proposal
         * composer, with its Context field already written: today the
         * *Propose a decision* entry in the Files ⋯ menu, which arrives as
         * `?team=…&propose=1&file=…` and hands over a markdown link to the
         * file.
         *
         * Consumed and cleared, so switching teams afterwards does not reopen
         * it. `immediate` because the prefill can be set while this component
         * is still mounting — the deep-link reader selects the team first,
         * which is what renders this view.
         */
        decisionsComposePrefill: {
            immediate: true,
            handler(prefill) {
                if (!prefill?.body) {
                    return
                }
                this.composeDecisionPrefill = prefill.body
                this.composeDecisionOpen = true
                this.SET_DECISIONS_COMPOSE_PREFILL(null)
            },
        },
        // v4.10.11 — the warm-up queue cannot decide which tabs boot a frame
        // until the team's resources are known; resume it when they are (and
        // only if it is idle: nothing in flight, no timer pending).
        'loading.resources'(isLoading) {
            if (!isLoading && this._preloadQueue?.length > 0
                && !this._preloadAwaiting && this._preloadTimers?.length === 0) {
                this.advancePreload()
            }
        },
        // v4.6.20 — a pin now moves the grid to the event's date rather than
        // starting a watcher on an iframe that no longer exists.
        calendarEmbedEvent(ev) {
            if (ev?.url) {
                this.$nextTick(() => this.showPinnedCalendarEvent(ev))
            }
        },

        currentTeamId(newId) {
            if (newId) {
                this._debouncedSave?.cancel()
                this._debouncedUserSave?.cancel()
                this.editingTeamPreset = false
                this.teamLayoutDraftSnapshot = null
                this.teamLayoutDraftTabOrderSnapshot = null
                this.teamLayoutDraftWasDefault = false
                this.skipNextPersonalLayoutSave = false
                this.gridLayout = []
                this.orderedTabs = []
                this.layoutLoaded = false
                this.editMode = false
                this.defaultTabAppliedFor = null
                this.preloadedViews = new Set()
                // v4.5.10 — re-arm the preload for the new team. Without this
                // the schedule only ever ran once, in mounted(), so from the
                // first team switch onwards every tab was a cold load.
                this.schedulePreload()
                this.SET_PRESENCE_CONFIG({ presence_enabled: false, hide_reasons: false })
                this.SET_DECISIONS_CONFIG({ decisions_enabled: false })
                // loadLayout now includes presenceConfig in its response,
                // so a single request is all we need. No race conditions.
                this.loadLayout(newId)
            }
        },
        // Project-owner onboarding (v3.90.x) — members (and thus isTeamAdmin)
        // resolve independently of loadLayout's project fact; whichever finishes
        // last is the one that actually triggers the auto-popup (idempotent).
        isTeamAdmin() {
            this.maybeShowProjectGuideForNewTeam()
        },
        // When ManageTeamView updates presenceConfig in the store (e.g. enabling
        // the presence tab toggle), rebuild the tab list immediately so the
        // Presence tab appears/disappears without a page reload.
        presenceConfig: {
            deep: true,
            handler() {
                this.buildOrderedTabs(this.orderedTabs.map(t => t.key))
            },
        },
        // v4.2.0 — when the admin changes the team's default tab in Manage
        // Team → Settings → Dashboard, the store's dashboardConfig.default_tab
        // updates immediately via SET_DASHBOARD_CONFIG. Reset the one-shot
        // guard and re-run applyDefaultTab so the currently-open team jumps to
        // the new default without needing a browser reload. applyDefaultTab is
        // idempotent and only fires when the user is still on Home, so it
        // never yanks someone off a tab they navigated to themselves.
        'dashboardConfig.default_tab'() {
            if (!this.layoutLoaded) return
            this.defaultTabAppliedFor = null
            this.applyDefaultTab()
        },
        // Manage Team changes these in the store without refetching the
        // separate bundle. Reload so enforcement controls update immediately.
        dashboardLayoutRevision() {
            if (this.currentTeamId && this.layoutLoaded && !this.editingTeamPreset) {
                this._debouncedSave?.cancel()
                this._debouncedUserSave?.cancel()
                this.loadLayout(this.currentTeamId)
            }
        },
        // Same pattern for decisionsConfig — rebuild tabs when per-team toggle changes.
        decisionsConfig: {
            deep: true,
            handler() {
                this.buildOrderedTabs(this.orderedTabs.map(t => t.key))
            },
        },
        timelineConfig: {
            deep: true,
            handler() {
                this.buildOrderedTabs(this.orderedTabs.map(t => t.key))
            },
        },
        // v4.3.8 — same rebuild-on-flip pattern for the Wiki (Collectives)
        // per-team toggle. Without this the Wiki iframe tab never appears
        // in the tab bar until a page reload, even though buildAllTabDescriptors
        // already checks collectivesConfig.collectives_enabled. Recurring
        // gap when adding new config-gated tabs — see the presenceConfig /
        // decisionsConfig / timelineConfig watchers above.
        collectivesConfig: {
            deep: true,
            handler() {
                this.buildOrderedTabs(this.orderedTabs.map(t => t.key))
            },
        },
        // v4.10.41 — the Services tab appears with the layout bundle's
        // serviceDeskConfig; rebuild when it arrives, as for the configs above.
        serviceDeskConfig: {
            deep: true,
            handler() {
                this.buildOrderedTabs(this.orderedTabs.map(t => t.key))
            },
        },
        // Budget tab appears once (a) the project fact confirms Advanced mode
        // AND (b) budget_enabled is true. Both arrive with the layout bundle,
        // but project may commit slightly before budgetConfig, and the tab
        // list is initially built while `project` still says isProject=false.
        // Rebuild on either change so the tab shows up as soon as the flag
        // that finally unlocks it flips.
        budgetConfig: {
            deep: true,
            handler() {
                this.buildOrderedTabs(this.orderedTabs.map(t => t.key))
            },
        },
        // Same rebuild-on-flip pattern as budgetConfig — the Time tab appears
        // once (a) project fact confirms Advanced mode AND (b) time_enabled
        // is true AND (c) can_view_time is true. All arrive with the layout
        // bundle but may commit slightly out of order.
        timeConfig: {
            deep: true,
            handler() {
                this.buildOrderedTabs(this.orderedTabs.map(t => t.key))
            },
        },
        project: {
            deep: true,
            handler() {
                this.buildOrderedTabs(this.orderedTabs.map(t => t.key))
            },
        },
        // The three registered sources. Each arrives on its own request, so
        // each needs its own watcher: a team whose only tab comes from a
        // package never changes the legacy array, and vice versa.
        webLinks() { this.syncRegisteredTabs() },
        externalMenuItems() { this.syncRegisteredTabs() },
        packageTabs() { this.syncRegisteredTabs() },

        /**
         * Sidebar 3-dot menu can request an action (Invite / Leave team) on a
         * team that isn't open yet. App.vue selects the team, then sets this
         * flag. We fire once the team is actually mounted and its resources
         * have loaded — checking currentTeamId prevents a cold-start race
         * where the flag arrives before the watcher re-mounts. Cleared after
         * consumption so the same action doesn't fire twice.
         */
        pendingTeamAction: {
            immediate: true,
            handler(action) {
                if (!action || !this.currentTeamId) return
                if (action === 'invite') {
                    this.showInviteModal = true
                } else if (action === 'leave') {
                    this.onLeaveTeam()
                }
                this.$store.commit('SET_PENDING_TEAM_ACTION', null)
            },
        },

        /**
         * v4.6.1 — the snap call that used to live here is gone; the grid
         * compacts itself when visibleLayout changes, which is exactly what a
         * resource appearing or disappearing causes.
         */
        resources: {
            deep: true,
            handler() {
                // v4.2.2 — resource additions/removals change which built-in
                // tabs isBuiltinTabRenderable considers valid, so the store's
                // availableTabs (source for the Default-tab select) needs to
                // recompute. Cheap: same buildOrderedTabs call the config
                // watchers already use with the current savedOrder.
                if (this.layoutLoaded) {
                    this.buildOrderedTabs(this.orderedTabs.map(t => t.key))
                }
            },
        },

        /**
         * When the user exits edit mode (true → false), immediately save so the
         * server has the final positions. Without this, a user who drags quickly
         * and exits edit mode before the 1.2 s debounce fires would not have
         * their arrangement persisted.
         *
         * v4.6.1 — the applySnap() that used to run first is gone. The grid has
         * already compacted during the drag, so gridLayout is current.
         */
        /**
         * v4.13.34 — enforcement can arrive while a member is mid-edit (a team
         * admin sets it, the member reopens the team). Shut edit mode rather
         * than leaving them arranging a grid the next load will replace.
         */
        layoutEnforced(enforced) {
            if (enforced) {
                this._debouncedSave?.cancel()
                this._debouncedUserSave?.cancel()
                if (this.editMode && !this.editingTeamPreset) this.editMode = false
            } else if (this.editingTeamPreset) {
                this.cancelTeamLayoutEdit()
            }
        },

        editMode(newVal, oldVal) {
            if (!newVal && oldVal && !this.layoutEnforced && !this.editingTeamPreset && !this.skipNextPersonalLayoutSave) {
                this.$nextTick(() => {
                    // 'user': leaving edit mode is the end of an arrangement
                    // the member made, even if the debounce never fired.
                    this.saveLayout('user')
                })
            }
        },
    },

    created() {
        // Two debounces over one endpoint, because the two callers mean
        // different things by a save (v4.13.33): a drag is the member
        // arranging their home, a tab reorder is not. See saveLayout.
        this._debouncedSave     = debounce(() => this.saveLayout('auto'), 1200)
        this._debouncedUserSave = debounce(() => this.saveLayout('user'), 1200)
    },

    async mounted() {
        if (typeof window !== 'undefined' && window.matchMedia) {
            // Mobile: phone portrait/landscape (≤768px) OR tablet portrait (≤1024px portrait)
            const mobileQuery = '(max-width: 768px), (max-width: 1024px) and (orientation: portrait)'
            this._mobileMql = window.matchMedia(mobileQuery)
            this.isMobile = this._mobileMql.matches
            this._mobileMqlHandler = (e) => {
                this.isMobile = e.matches
                // isTablet is the middle zone — recalculate when mobile changes
                this.isTablet = !e.matches && this._tabletMql?.matches
            }
            if (typeof this._mobileMql.addEventListener === 'function') {
                this._mobileMql.addEventListener('change', this._mobileMqlHandler)
            } else if (typeof this._mobileMql.addListener === 'function') {
                this._mobileMql.addListener(this._mobileMqlHandler)
            }

            // Tablet landscape: ≤1200px landscape AND not already mobile
            const tabletQuery = '(max-width: 1200px) and (orientation: landscape)'
            this._tabletMql = window.matchMedia(tabletQuery)
            this.isTablet = !this.isMobile && this._tabletMql.matches
            this._tabletMqlHandler = (e) => {
                this.isTablet = !this.isMobile && e.matches
            }
            if (typeof this._tabletMql.addEventListener === 'function') {
                this._tabletMql.addEventListener('change', this._tabletMqlHandler)
            } else if (typeof this._tabletMql.addListener === 'function') {
                this._tabletMql.addListener(this._tabletMqlHandler)
            }
        }

        // The dashboard layout is the critical first request. Previously a
        // slow optional Intravox capability probe held it up (including the
        // 3-second fallback request when that app was absent), making a new
        // team's Home look empty after creation. Start layout loading first.
        if (this.currentTeamId) {
            this.loadLayout(this.currentTeamId)
        }
        await this.$store.dispatch('checkIntravox')
        this.schedulePreload()

        // Timeline crowding-badge navigation (v3.78.4) — the timeline.php
        // iframe has no navigation state of its own (view mode + window
        // start live here, in timelineViewMode/timelineWindowStart, exactly
        // like the Calendar tab). When a count-badge inside the iframe is
        // clicked, it can't just navigate itself; it posts a message up to
        // this window instead, and we react by switching the view here —
        // which then flows back down through the timelineUrl computed
        // property and reloads the iframe at the new view/window.
        this._onTimelineMessage = (event) => {
            if (event.origin !== window.location.origin) return
            const data = event.data
            if (!data || data.app !== 'teamhub' || data.type !== 'timeline-navigate') return
            if (typeof data.from !== 'number') return
            this.timelineViewMode = '1W'
            this.timelineWindowStart = TeamView_snapWindow(new Date(data.from * 1000), '1W')
        }
        window.addEventListener('message', this._onTimelineMessage)
    },

    // v4.5.10 — was beforeDestroy(), which Vue 3 never calls, so the media-query
    // listeners and the timeline message listener below leaked on unmount. The
    // preload timers added here need real teardown, so this file is fixed too;
    // the remaining components with the dead hook are logged in HANDOFF.
    beforeUnmount() {
        this.cancelPreload()
        for (const key of ['_mobileMql', '_tabletMql']) {
            const mql = this[key]
            const handler = this[key.replace('Mql', 'MqlHandler')]
            if (mql && handler) {
                if (typeof mql.removeEventListener === 'function') {
                    mql.removeEventListener('change', handler)
                } else if (typeof mql.removeListener === 'function') {
                    mql.removeListener(handler)
                }
            }
            this[key] = null
            this[key.replace('Mql', 'MqlHandler')] = null
        }
        if (this._onTimelineMessage) {
            window.removeEventListener('message', this._onTimelineMessage)
            this._onTimelineMessage = null
        }
    },

    methods: {
        t,
        ...mapActions(['selectTeam']),
        // v4.6.15 — the layout bundle's commits moved to the store's
        // loadTeamLayout action, so the mutations this component mapped only to
        // unpack that response went with them. What is left is what TeamView
        // still writes itself.
        ...mapMutations(['SET_VIEW', 'SET_PRESENCE_CONFIG', 'SET_DECISIONS_CONFIG', 'SET_DECISIONS_TARGET', 'SET_DECISIONS_COMPOSE_PREFILL', 'SET_PROJECT', 'SET_PROJECT_TAB_FOCUS']),

        setView(view) { this.SET_VIEW(view) },

        /**
         * v4.13.9 — open the OpenProject work-package modal. `0` creates;
         * an id changes that work package.
         *
         * The id is set before the flag, so the `:key` is already right
         * when the modal mounts — otherwise Vue would build it for the
         * previous id and immediately rebuild it.
         *
         * @param {number} workPackageId 0 to create, otherwise the id
         */
        openOpenProjectWorkPackage(workPackageId = 0) {
            this.editOpenProjectWorkPackageId = Number(workPackageId) || 0
            this.showAddOpenProjectWorkPackage = true
        },

        /**
         * Mark a view as preloaded so its iframe is created (and starts
         * loading) before the user asks for it. Idempotent; replaces the Set so
         * the v-ifs that read it stay reactive.
         */
        preloadView(view) {
            if (!view || this.preloadedViews.has(view)) {
                return
            }
            const next = new Set(this.preloadedViews)
            next.add(view)
            this.preloadedViews = next
        },

        /**
         * Warm the built-in app tabs after a team is opened, so clicking one is
         * instant rather than a cold NC app boot — **one app at a time, Files
         * first** (v4.10.11).
         *
         * Runs on mount AND on every team switch — `preloadedViews` is cleared
         * per team, so a schedule that only fired once left every tab cold from
         * the first switch onwards (fixed v4.5.10).
         *
         * Why sequential and not a timer stagger: measured on the test
         * instance, a Files page is ~20 MB of JavaScript from every app that
         * hooks into Files, Talk ~32 MB, Deck ~30 MB, Collectives ~25 MB — all
         * cached, all parsed and executed on the parent's own main thread,
         * because same-origin frames share it. The old 400 ms stagger had four
         * of those booting together within three seconds of arrival: Files
         * took 7.3 s instead of the 5.9 s it takes alone, and the Home tab the
         * user was actually looking at was janky throughout. Now the next app
         * starts only when the previous frame has fired `load` and had a
         * moment to render (or a timeout has passed, so a frame that never
         * loads cannot hold the rest hostage). The tab on screen always goes
         * first; hover intent (TeamTabBar's `preload` event) still jumps the
         * queue for the tab the user is reaching for.
         */
        schedulePreload() {
            this.cancelPreload()
            // Files first, per the decision of 2026-09-21: it is the tab most
            // often opened from a widget and the one whose cold boot is felt.
            // Calendar and the Advanced-project timeline are native views and
            // cost only a paint; Collectives goes last because its per-team
            // config rides on the layout bundle, which may land after the
            // resources do.
            this._preloadQueue = ['files', 'talk', 'deck', 'calendar', 'timeline', 'collectives']
            this._loadedEmbeds = new Set()
            this.advancePreload()
        },

        /**
         * Start the next warm-up, or wait for the one in flight.
         *
         * Nothing starts until the team's resources are known: whether a view
         * boots a frame at all depends on them, and deciding on an empty
         * `resources` would skip every app tab (the `loading.resources`
         * watcher calls back in).
         */
        advancePreload() {
            this.clearPreloadWait()
            if (this.loading?.resources) {
                return
            }
            // The tab on screen always goes first: if the user opened an app
            // tab that is still booting, nothing else may compete with it.
            const active = this.currentView
            if (this.embedBoots(active) && !this._loadedEmbeds.has(active)) {
                this.awaitEmbed(active)
                return
            }
            while (this._preloadQueue.length > 0) {
                const view = this._preloadQueue.shift()
                if (this._loadedEmbeds.has(view)) {
                    continue
                }
                this.preloadView(view)
                if (this.embedBoots(view)) {
                    this.awaitEmbed(view)
                    return
                }
                // A native view: give it one frame's worth of breathing room
                // and move on.
                this._preloadTimers.push(setTimeout(() => this.advancePreload(), PRELOAD_NATIVE_GAP_MS))
                return
            }
        },

        /**
         * Does this view boot a Nextcloud app in an iframe for this team?
         * False for native views (the Calendar grid, an Advanced project's
         * timeline) and for app tabs the team has no resource for — those
         * never mount, so they must never be waited on.
         *
         * @param {string} view
         * @return {boolean}
         */
        embedBoots(view) {
            switch (view) {
            case 'talk':        return !!this.resources?.talk
            case 'files':       return !!this.resources?.files
            case 'deck':        return (this.resources?.deck || []).length > 0
            case 'collectives': return !!this.collectivesConfig?.collectives_enabled
            case 'timeline':    return !!this.currentTeamId && !this.isAdvancedProject
            default:            return false
            }
        },

        /** Wait for `view`'s frame to load, bounded. */
        awaitEmbed(view) {
            this._preloadAwaiting = view
            this._preloadTimers.push(setTimeout(() => {
                this._preloadAwaiting = null
                this.advancePreload()
            }, PRELOAD_LOAD_TIMEOUT_MS))
        },

        /**
         * An embed's frame fired `load`. Marks it warm (so it is kept alive
         * across tab switches even when opened by a click rather than the
         * queue) and, if it was the one being waited on, lets the queue move
         * on once the app has had a moment to fetch and render.
         *
         * @param {string} view
         */
        onEmbedLoaded(view) {
            this._loadedEmbeds?.add(view)
            this.preloadView(view)
            if (view !== this._preloadAwaiting) {
                return
            }
            this.clearPreloadWait()
            this._preloadTimers.push(setTimeout(() => this.advancePreload(), PRELOAD_SETTLE_MS))
        },

        /** Drop the in-flight wait and any pending timers. */
        clearPreloadWait() {
            this._preloadAwaiting = null
            if (Array.isArray(this._preloadTimers)) {
                this._preloadTimers.forEach(id => clearTimeout(id))
            }
            this._preloadTimers = []
        },

        /** Abandon the queue so a previous team's schedule can't fire late. */
        cancelPreload() {
            this.clearPreloadWait()
            this._preloadQueue = []
            this._loadedEmbeds = new Set()
        },

        /**
         * Apply the team's configured default tab on first open. The owner/admin
         * picks it in Manage Team → Settings → Dashboard; it rides in on the
         * layout bundle as dashboardConfig.default_tab. Fires at most once per
         * team open (defaultTabAppliedFor guard, reset on team change), only
         * while the user is still on Home — so it never yanks them off a tab a
         * deep-link already opened — and only when the target tab is actually
         * available. Anything unavailable falls back to Home (msgstream) by
         * simply doing nothing.
         */
        applyDefaultTab() {
            if (this.defaultTabAppliedFor === this.currentTeamId) return
            this.defaultTabAppliedFor = this.currentTeamId

            const target = this.dashboardConfig?.default_tab || 'msgstream'
            if (target === 'msgstream') return
            // Never override a view a deep-link (or the user) already switched to.
            if (this.currentView !== 'msgstream') return
            // Fall back to Home when the configured tab isn't currently available
            // (integration removed, project left advanced mode, etc.).
            if (!(this.orderedTabs || []).some(tab => tab.key === target)) return

            this.SET_VIEW(target)
        },
        /**
         * v4.13.34 — the second half of the enforced-layout gate. The button
         * is already greyed (TeamTabBar), and this is the boundary: a disabled
         * control is a presentation and a keyboard, a stale prop or a
         * re-render can all get past one.
         *
         * The server does not need this check — an enforced layout is served
         * regardless of what the client thinks, and a save would be overridden
         * on the next load — but a member who got into edit mode and dragged a
         * card would watch their work disappear, which is worse than not
         * getting in.
         */
        toggleEditMode() {
            if (this.teamLayoutActionBusy) return
            // A team-admin draft has its own publish/cancel lifecycle. Treat
            // the top-bar Done as Publish; the Cancel action in the edit banner
            // explicitly discards the draft. Never change the meaning of a
            // personal Done button halfway through a save.
            if (this.editingTeamPreset) {
                this.publishTeamLayoutDraft()
                return
            }
            if (this.layoutEnforced) {
                if (!this.canSetTeamDefault || !this.layoutLoaded) return
                this._debouncedSave?.cancel()
                this._debouncedUserSave?.cancel()
                this.teamLayoutDraftSnapshot = this.gridLayout.map(item => ({ ...item }))
                this.teamLayoutDraftTabOrderSnapshot = this.orderedTabs.map(tab => tab.key)
                this.teamLayoutDraftWasDefault = this.layoutIsDefault
                this.layoutIsDefault = false // never repack an admin draft
                this.editingTeamPreset = true
                this.editMode = true
                return
            }
            this.editMode = !this.editMode
        },

        /** Close any editor without writing a personal grid to the server. */
        async closeEditModeForTeamPublish() {
            this.skipNextPersonalLayoutSave = true
            this.editMode = false
            await this.$nextTick() // let the editMode watcher observe the guard
            this.skipNextPersonalLayoutSave = false
        },

        async publishTeamLayoutDraft() {
            if (!this.editingTeamPreset || !this.canSetTeamDefault || !this.currentTeamId || this.teamLayoutActionBusy) return
            const teamId = this.currentTeamId
            this.teamLayoutActionBusy = true
            try {
                await axios.put(generateUrl(`/apps/teamhub/api/v1/teams/${teamId}/dashboard/config`), {
                    team_layout: this.gridLayout,
                    team_tab_order: this.orderedTabs.map(t => t.key),
                    team_layout_mode: this.teamPreset?.mode || 'enforce',
                })
                if (teamId !== this.currentTeamId) return
                await this.closeEditModeForTeamPublish()
                this.editingTeamPreset = false
                this.teamLayoutDraftSnapshot = null
                this.teamLayoutDraftTabOrderSnapshot = null
                await this.loadLayout(teamId)
                showSuccess(t('teamhub', 'Team layout published'))
            } catch (err) {
                // Keep the draft editable after a rejected publish; nothing
                // has been written as a personal layout.
                showError(err?.response?.data?.error || t('teamhub', 'Failed to save the default layout'))
            } finally {
                this.teamLayoutActionBusy = false
            }
        },

        async cancelTeamLayoutEdit() {
            if (!this.editingTeamPreset) return
            this.gridLayout = (this.teamLayoutDraftSnapshot || []).map(item => ({ ...item }))
            this.buildOrderedTabs(this.teamLayoutDraftTabOrderSnapshot || [])
            this.layoutIsDefault = this.teamLayoutDraftWasDefault
            // Restore the enforced lock BEFORE Vue gets a chance to repack
            // the restored grid. A team-admin draft is not a template recipe.
            this.editingTeamPreset = false
            await this.closeEditModeForTeamPublish()
            this.teamLayoutDraftSnapshot = null
            this.teamLayoutDraftTabOrderSnapshot = null
        },

        // v4.11.18 — `openDecisionCompose(supersedesId)` is gone with the
        // open-proposal *Supersede* button it existed for. Nothing else ever
        // called it, and a proposal cannot name what it will replace: that is
        // now an approver's act on the approved decision being retired.
        // `PostMessageForm` still reads the handshake global for the plain
        // "open in decision mode" case.

        // Session A — open the focused compose modal.
        openCompose() {
            // v4.11.42 — blank: the prefill belongs to the deep link that set
            // it, not to the next person who presses *Propose decision*.
            this.composeDecisionPrefill = ''
            this.composeDecisionOpen = true
        },

        /** v4.11.42 — one place to close it, so the prefill never outlives it. */
        closeCompose() {
            this.composeDecisionOpen = false
            this.composeDecisionPrefill = ''
        },

        // Fired by ComposeDecisionModal after a successful proposal.
        // The payload is the new message object with .decision embedded.
        // We navigate to the Decisions tab and select the new decision
        // so the user lands on its detail view immediately.
        async onDecisionCreatedFromCompose(message) {
            const decision = message?.decision || null
            this.closeCompose()
            // Switch to the Decisions view.
            this.SET_VIEW('decisions')
            // Hand the messageId off via the store mutation so TeamDecisionsView's
            // watcher picks it up and scrolls/selects on next render.
            if (decision && decision.messageId) {
                this.$nextTick(() => {
                    this.SET_DECISIONS_TARGET(decision.messageId)
                })
            }
        },

        // ── Layout load / save ──────────────────────────────────────

        /**
         * v4.6.15 — the bundle's GET and the thirteen per-team commits that
         * follow it moved to the store's `loadTeamLayout` action, because
         * Manage Team needs the same facts on the paths where this component
         * never mounts. What stays here is what is genuinely this component's:
         * the widget grid and the tab arrangement.
         */
        async loadLayout(teamId) {
            try {
                const data = await this.$store.dispatch('loadTeamLayout', teamId)
                this.gridLayout        = Array.isArray(data.layout)      ? data.layout      : []
                this.userDefaultLayout = Array.isArray(data.userDefault) ? data.userDefault : []
                // v4.13.33 — the server says whether this came from the
                // cascade. It has been on the response since the endpoint was
                // written and nothing read it, which is why a default could
                // never be told apart from an arrangement once it was on
                // screen.
                this.layoutIsDefault   = data.isDefault === true
                this.canSetTeamDefault = data.canSetTeamDefault === true
                this.teamPreset        = data.teamPreset
                    || { mode: null, hasLayout: false, layout: null, updatedAt: null }
                // Project-owner onboarding (v3.90.x) — project is ready now; members
                // may or may not be (fetchMembers resolves independently via the
                // store's selectTeam action) — the isTeamAdmin watcher below covers
                // that ordering. Idempotent, so calling from both places is safe.
                this.maybeShowProjectGuideForNewTeam()
                this.buildOrderedTabs(Array.isArray(data.tabOrder) ? data.tabOrder : [])
                this.layoutLoaded = true
                this.applyDefaultTab()
            } catch (err) {
                console.warn('[TeamHub][TeamView] loadLayout: failed', err?.message)
                this.gridLayout = []
                this.layoutIsDefault = false
                this.canSetTeamDefault = false
                this.teamPreset = { mode: null, hasLayout: false, layout: null, updatedAt: null }
                this.buildOrderedTabs([])
                this.layoutLoaded = true
            }
        },

        /**
         * Persist this team's layout and tab order.
         *
         * v4.13.33 — `origin` says whether a person arranged what is being
         * saved. The server only ever promotes it, so a tab reorder (which
         * says nothing about the grid) cannot mark a cascaded layout as
         * arranged, and cannot un-mark one that is. Every caller that saves
         * because the member moved, resized or collapsed a card passes
         * `'user'`; see LayoutMapper::upsert.
         */
        async saveLayout(origin = 'auto') {
            if (!this.currentTeamId || !this.layoutLoaded || this.layoutEnforced || this.editingTeamPreset) return
            const tabOrder = this.orderedTabs.map(t => t.key)
            try {
                await axios.put(
                    generateUrl(`/apps/teamhub/api/v1/teams/${this.currentTeamId}/layout`),
                    { layout: this.gridLayout, tabOrder, origin },
                )
                if (origin === 'user') this.layoutIsDefault = false
            } catch (err) {
                console.warn('[TeamHub][TeamView] saveLayout: failed', err?.response?.status, err?.message)
            }
        },

        /**
         * The grid moved something. In edit mode that is the member dragging
         * or resizing a card, which is an arrangement of their own; outside it
         * this fires on the library's own recomputes and is not saved at all.
         */
        onLayoutUpdated(newLayout) {
            if (this.layoutEnforced && !this.editingTeamPreset) return
            this.gridLayout = newLayout
            if (this.editingTeamPreset) return // draft, published through dashboard/config only
            if (this.editMode && this.layoutLoaded) {
                // Flipped here and not when the save returns: the save is
                // debounced by 1.2 s, and for that whole window the grid would
                // otherwise still consider this a cascaded layout and be free
                // to repack over the drag that is in progress.
                this.layoutIsDefault = false
                this._debouncedUserSave()
            }
        },

        /**
         * v4.13.33 — the grid arranged itself: a cascaded layout packed to the
         * widgets this team shows, or a canvas card brought up to its size.
         *
         * **Deliberately not saved.** A packed default is computed from the
         * order the server sends and the widgets the team has, both of which
         * this client already holds, so recomputing it on every load costs
         * nothing — and not saving it is what keeps the member on the cascade,
         * where a later change to the default can still reach them. Saving it
         * is exactly what v4.0.8's auto-fit pass did, and it froze every
         * member's home on first open (DESIGN §2.206).
         */
        onLayoutArranged(newLayout) {
            this.gridLayout = newLayout
        },

        onTabReorder() {
            if (!this.layoutLoaded || this.editingTeamPreset) return
            // Tab navigation is always a personal choice, even on an enforced
            // team grid. The dedicated endpoint never changes the saved grid.
            this._debouncedSave?.cancel()
            this._debouncedUserSave?.cancel()
            this.saveTabOrder()
        },

        async saveTabOrder() {
            if (!this.currentTeamId || !this.layoutLoaded) return
            try {
                await axios.put(generateUrl(`/apps/teamhub/api/v1/teams/${this.currentTeamId}/layout/tabs`), {
                    tabOrder: this.orderedTabs.map(tab => tab.key),
                })
            } catch (err) {
                console.warn('[TeamHub][TeamView] saveTabOrder: failed', err?.response?.status, err?.message)
            }
        },

        // ── Team-wide layout controls (issue #109, v4.13.36) ────────────

        /**
         * All team-wide layout actions use the same admin-gated endpoint.
         * The server authoritatively checks team-admin permissions. Keep
         * personal saves and draft publishing out of this path, and reload
         * the layout bundle after a successful policy change so the toolbar
         * and grid always reflect the new enforcement state.
         */
        async changeTeamLayout(payload, successMessage) {
            if (!this.currentTeamId || !this.canSetTeamDefault || this.teamLayoutActionBusy || this.editMode) return
            const teamId = this.currentTeamId
            this.teamLayoutActionBusy = true
            this._debouncedSave?.cancel()
            this._debouncedUserSave?.cancel()
            try {
                const { data } = await axios.put(
                    generateUrl(`/apps/teamhub/api/v1/teams/${teamId}/dashboard/config`),
                    payload,
                )
                if (teamId !== this.currentTeamId) return
                this.$store.commit('SET_DASHBOARD_CONFIG', data)
                await this.loadLayout(teamId)
                showSuccess(successMessage)
            } catch (err) {
                if (teamId === this.currentTeamId) {
                    showError(err?.response?.data?.error || t('teamhub', 'Failed to save the default layout'))
                }
            } finally {
                this.teamLayoutActionBusy = false
            }
        },

        /**
         * A team admin unlocks from the enforced layout's draft editor.
         * Keep the LAST PUBLISHED team layout; never publish the work-in-progress
         * grid as a side effect of changing permissions. Existing member-specific
         * layouts may reappear after the enforced policy is removed.
         */
        async unlockTeamLayout() {
            if (!this.layoutEnforced || !this.hasTeamLayout || !this.canSetTeamDefault
                || !this.editingTeamPreset || !this.currentTeamId || this.teamLayoutActionBusy) return
            const teamId = this.currentTeamId

            // An admin may have moved or resized widgets in the draft. Require
            // confirmation before discarding those unpublished changes.
            const draftChanged = JSON.stringify(this.gridLayout) !== JSON.stringify(this.teamLayoutDraftSnapshot)
                || JSON.stringify(this.orderedTabs.map(tab => tab.key)) !== JSON.stringify(this.teamLayoutDraftTabOrderSnapshot)
            if (draftChanged) {
                const confirmed = await showConfirmation({
                    name: t('teamhub', 'Unlock layout'),
                    text: t('teamhub', 'Unlocking will discard unpublished layout changes. Continue?'),
                    labelConfirm: t('teamhub', 'Unlock layout'),
                    labelReject: t('teamhub', 'Cancel'),
                    severity: 'warning',
                })
                if (!confirmed || teamId !== this.currentTeamId || !this.editingTeamPreset || this.teamLayoutActionBusy) return
            }

            this.teamLayoutActionBusy = true
            this._debouncedSave?.cancel()
            this._debouncedUserSave?.cancel()
            try {
                const { data } = await axios.put(
                    generateUrl(`/apps/teamhub/api/v1/teams/${teamId}/dashboard/config`),
                    { team_layout_mode: 'apply_once' },
                )
                if (teamId !== this.currentTeamId) return
                // Discard the draft BEFORE updating enforcement in the store;
                // otherwise the enforcement watcher would race the editor close.
                await this.cancelTeamLayoutEdit()
                this.$store.commit('SET_DASHBOARD_CONFIG', data)
                await this.loadLayout(teamId)
                showSuccess(t('teamhub', 'Unlock layout'))
            } catch (err) {
                if (teamId === this.currentTeamId) {
                    showError(err?.response?.data?.error || t('teamhub', 'Failed to save the default layout'))
                }
            } finally {
                this.teamLayoutActionBusy = false
            }
        },

        async resetTeamLayoutToTemplate() {
            if (!this.hasTeamLayout) return
            // Keep the current enforce/apply mode; server resolves the team's
            // template, applies the recipe, and compact-packs missing widgets.
            await this.changeTeamLayout(
                { reset_team_layout: true },
                t('teamhub', 'Reset to template'),
            )
        },

        // ── Widget gating ───────────────────────────────────────────

        // v4.6.15 — getActiveWidgetIds() and buildDashboardWidgetCatalog() moved
        // to src/lib/teamTabs.js. Both existed only to feed the store, and the
        // store is now what builds them, so Manage Team gets the same lists on
        // the paths where this component never mounts.

        // v4.6.1 — applySnap() removed. It reimplemented the compaction that
        // grid-layout-plus already does, and got it wrong in two ways: it
        // grouped columns by exact x equality (so a w=3 widget dragged from
        // x=9 to x=8 became its own column and repacked to y=0 over the x=9
        // stack), and it parked inactive widgets at y=9999, which then leaked
        // into every "bottom of the column" calculation and pushed newly-added
        // widgets thousands of rows down the page. The grid now runs with
        // :vertical-compact="true" and compacts during the drag instead.

        // ── Default layout actions ──────────────────────────────────

        /**
         * Save a personal default for this team's template ONLY. The server
         * validates membership and derives the type rather than using a
         * client-provided template key. Other team types are unaffected.
         */
        async setAsDefault() {
            if (!this.currentTeamId || !this.teamType || this.layoutEnforced) return
            const teamId = this.currentTeamId
            // Avoid a queued personal save marking this very grid as a local
            // override immediately after the server rolls out the type default.
            this._debouncedSave?.cancel()
            this._debouncedUserSave?.cancel()
            try {
                const tabOrder = this.orderedTabs.map(t => t.key)
                await axios.put(
                    generateUrl('/apps/teamhub/api/v1/layout/default'),
                    { teamId, layout: this.gridLayout, tabOrder },
                )
                if (teamId !== this.currentTeamId) return
                await this.closeEditModeForTeamPublish()
                await this.loadLayout(teamId)
                showSuccess(t('teamhub', 'Type default layout saved'))
            } catch (err) {
                showError(err?.response?.data?.error || t('teamhub', 'Failed to save default layout'))
            }
        },

        /**
         * v4.13.34 — make the arrangement in front of us this team's own
         * default (issue #109 phase 3).
         *
         * Publishing a team-wide default enforces that exact edited layout;
         * it is the only way to establish a lock. No separate Lock action
         * exists. Once saved, exit the personal editor before loading policy.
         * To unlock later, an admin edits the enforced preset and chooses Unlock.
         */
        async saveAsTeamDefault() {
            if (!this.canSetTeamDefault || !this.currentTeamId) return
            const teamId = this.currentTeamId
            // A personal edit may have a queued debounce. Cancel it BEFORE
            // the request so it cannot write while enforcement is changing.
            this._debouncedSave?.cancel()
            this._debouncedUserSave?.cancel()
            const saved = await this.saveLayoutDefault(
                `/apps/teamhub/api/v1/teams/${teamId}/dashboard/config`,
                {
                    team_layout: this.gridLayout,
                    team_tab_order: this.orderedTabs.map(t => t.key),
                    team_layout_mode: 'enforce',
                },
                t('teamhub', 'Team layout saved.'),
            )
            if (!saved || teamId !== this.currentTeamId) return

            // The save can turn a flexible layout into an enforced preset.
            // Exit the old PERSONAL editor before loading that policy; keeping
            // it open made Done turn into Cancel and could schedule a personal
            // layout write that the API (correctly) rejects with 403.
            await this.closeEditModeForTeamPublish()
            await this.loadLayout(teamId)
        },

        /**
         * One PUT, one toast, one error path.
         *
         * v4.13.35 — one caller left. `saveAsTemplateDefault` and
         * `saveAsInstanceDefault` are gone: those are Nextcloud administrator
         * tasks and they belong in Admin -> TeamHub -> Policy, not in whichever
         * team the administrator happens to be a member of (Justin,
         * 2026-10-28). Kept as a helper rather than inlined because the error
         * handling is the part worth keeping: the server's own message is
         * shown when it sends one, since the refusals that matter here are
         * specific and worth reading.
         */
        async saveLayoutDefault(url, payload, successMessage) {
            try {
                await axios.put(generateUrl(url), payload)
                showSuccess(successMessage)
                return true
            } catch (err) {
                showError(err?.response?.data?.error || t('teamhub', 'Failed to save the default layout'))
                return false
            }
        },

        /**
         * v4.13.34 — the member takes the team's suggested layout.
         *
         * Saved as their own arrangement (`origin: 'user'`), because that is
         * what it now is: they chose it. It therefore survives a later change
         * to the suggestion, which is the difference between taking an offer
         * and following a default.
         */
        async applyTeamPreset() {
            if (this.layoutEnforced) return
            const preset = this.teamPreset?.layout
            if (!Array.isArray(preset) || preset.length === 0) return

            this.gridLayout = preset.map(item => ({ ...item }))
            await this.saveLayout('user')
            showSuccess(t('teamhub', 'Team layout applied.'))
        },

        /**
         * Explicitly reset this one team to its Nextcloud admin template.
         * This bypasses the user's type default without changing that default
         * for their other teams. The server stores a template-reset marker
         * and keeps tab ordering personal. An enforced preset cannot be reset
         * by an ordinary member; team admins reset the team-wide layout from
         * the actions beside Edit team layout on Home.
         */
        async resetToDefault() {
            if (!this.currentTeamId || this.layoutEnforced) return
            const teamId = this.currentTeamId
            this._debouncedSave?.cancel()
            this._debouncedUserSave?.cancel()
            // Leaving edit mode normally saves a personal grid. Suppress it:
            // such a save would race and undo the reset to the template.
            await this.closeEditModeForTeamPublish()
            try {
                await axios.delete(generateUrl(`/apps/teamhub/api/v1/teams/${teamId}/layout`))
                if (teamId === this.currentTeamId) await this.loadLayout(teamId)
            } catch (err) {
                showError(err?.response?.data?.error || t('teamhub', 'Failed to reset layout'))
            }
