        buildOrderedTabs(savedOrder) {
            this.orderedTabs = orderTabDescriptors(buildAllTabDescriptors(this.$store.state), savedOrder)
            this.$store.dispatch('publishTeamTabs', {
                teamId: this.currentTeamId,
